source /home/agent/deploy.env
PGFQDN="$PGNAME.postgres.database.azure.com"
DBURL="postgresql://$PGUSER:[REDACTED:conn-password]@$PGFQDN:5432/umami?sslmode=require"
python3 - "$LOC" "$SUB" "$RG" "$ENVNAME" "$DBURL" "$APPSECRET" > /tmp/app.json <<'EOF'
import json,sys
loc,sub,rg,env,dburl,secret=[REDACTED:value]]
body={
 "location":loc,
 "tags":{"run":"acs3e3f1791","app":"umami"},
 "properties":{
  "managedEnvironmentId":f"/subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.App/managedEnvironments/{env}",
  "configuration":{
    "activeRevisionsMode":"Single",
    "ingress":{"external":True,"targetPort":3000,"transport":"auto","allowInsecure":False,
               "traffic":[{"latestRevision":True,"weight":100}]},
    "secrets":[{"name":"database-url","value":dburl},{"name":"app-secret","value":secret}]
  },
  "template":{
    "containers":[{
      "name":"umami",
      "image":"docker.umami.is/umami-software/umami@sha256:fa32d116cf20cad52cbc3fad9a63b46e7fa02299d8f967168eb453d49c476b4a",
      "resources":{"cpu":1.0,"memory":"2.0Gi"},
      "env":[{"name":"DATABASE_URL","secretRef":"database-url"},
             {"name":"APP_SECRET","secretRef":"app-secret"},
             {"name":"DATABASE_TYPE","value":"postgresql"},
             {"name":"HOSTNAME","value":"0.0.0.0"}],
      "probes":[
        {"type":"Startup","httpGet":{"path":"/api/heartbeat","port":3000},"initialDelaySeconds":20,"periodSeconds":10,"failureThreshold":30,"timeoutSeconds":5},
        {"type":"Readiness","httpGet":{"path":"/api/heartbeat","port":3000},"periodSeconds":10,"failureThreshold":6,"timeoutSeconds":5}
      ]
    }],
    "scale":{"minReplicas":1,"maxReplicas":1}
  }
 }
}
print(json.dumps(body))
EOF
/home/agent/arm.sh PUT "/subscriptions/$SUB/resourceGroups/$RG/providers/Microsoft.App/containerApps/$APPNAME?api-version=2024-03-01" "$(cat /tmp/app.json)" > /tmp/appresp.json
grep -i '^HTTP/' /tmp/hdr.txt
python3 -c "
import json;d=json.load(open('/tmp/appresp.json'))
if 'error' in d: print('ERROR',json.dumps(d)[:800])
else: print(d['properties']['provisioningState'], d['properties'].get('configuration',{}).get('ingress',{}).get('fqdn'))"

